Write a C program that parses PE headers and extracts key information:

```c
#include <windows.h>
#include <stdio.h>

int main(int argc, char* argv[]) {
    FILE* f = fopen(argv[1], "rb");
    IMAGE_DOS_HEADER dosHeader;
    fread(&dosHeader, sizeof(dosHeader), 1, f);

    // Verify MZ signature
    if (dosHeader.e_magic != IMAGE_DOS_SIGNATURE) {
        printf("Not a valid PE file!\n");
        return 1;
    }

    // Seek to PE header
    fseek(f, dosHeader.e_lfanew, SEEK_SET);
    IMAGE_NT_HEADERS ntHeaders;
    fread(&ntHeaders, sizeof(ntHeaders), 1, f);

    printf("Machine: %x\n", ntHeaders.FileHeader.Machine);
    printf("Sections: %d\n", ntHeaders.FileHeader.NumberOfSections);
    printf("Entry Point: 0x%x\n", ntHeaders.OptionalHeader.AddressOfEntryPoint);
    printf("Image Base: 0x%llx\n", ntHeaders.OptionalHeader.ImageBase);

    fclose(f);
    return 0;
}
```

Compile with: `cl pe_parser.c` or `gcc pe_parser.c -o pe_parser.exe`

Then analyze a real executable: `pe_parser.exe C:\Windows\notepad.exe`
